import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.7R1OEGYz.js";const p=JSON.parse('{"title":"Send and the guard","description":"","frontmatter":{},"headers":[],"relativePath":"using/send.md","filePath":"using/send.md"}'),o={name:"using/send.md"};function s(i,e,d,h,l,c){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="send-and-the-guard" tabindex="-1">Send and the guard <a class="header-anchor" href="#send-and-the-guard" aria-label="Permalink to &quot;Send and the guard&quot;">​</a></h1><p>Sending is where Suho earns its name. The wallet resolves who you are paying and warns you before you pay a stranger.</p><h2 id="sending-to-a-name" tabindex="-1">Sending to a name <a class="header-anchor" href="#sending-to-a-name" aria-label="Permalink to &quot;Sending to a name&quot;">​</a></h2><p>Type a up.id name or a 0x address in the recipient field. The app resolves it live, with a short debounce.</p><ul><li><strong>Verified human.</strong> The recipient card shows a red seal and &quot;Verified human&quot;. Enter an amount and send.</li><li><strong>Unverified address.</strong> The card shows an amber warning: &quot;Unverified address. Suho can&#39;t identify who this is.&quot;</li></ul><p>Enter the amount and tap Send. Complete the passkey prompt. A toast tracks the transaction: pending, then &quot;Sent&quot; with the real measured confirmation time, then &quot;Confirmed&quot; with an explorer link.</p><p>A verified send is proven live. <a href="https://sepolia-explorer.giwa.io/tx/0x5140fa4f8d3081b8f1accd82b1df4c157410cd055c888aead21463ff1263c8ec" target="_blank" rel="noreferrer">View the transaction.</a></p><h2 id="the-guard" tabindex="-1">The guard <a class="header-anchor" href="#the-guard" aria-label="Permalink to &quot;The guard&quot;">​</a></h2><p>Every transfer passes through <code>OndolTransferGuard</code> before it runs. The guard decides one of three outcomes.</p><ul><li><strong>Verified recipient.</strong> Allowed silently.</li><li><strong>Unverified recipient, small amount.</strong> Allowed with a warning event. The app shows the amber card. The chain does not block small sends.</li><li><strong>Unverified recipient, large amount.</strong> Allowed only after an explicit hold-to-confirm, then your passkey. The threshold is 0.01 ether. The guard emits a loud <code>UnverifiedLargeSend</code> event so the send is never silent.</li></ul><p>A small warned send is proven live. <a href="https://sepolia-explorer.giwa.io/tx/0xf1ab1cdc2243ea49fc054a4b6fd4e54edb6bde80be7d04be6494d8fc37bf300d" target="_blank" rel="noreferrer">View the transaction.</a></p><h2 id="the-large-send-confirmation" tabindex="-1">The large-send confirmation <a class="header-anchor" href="#the-large-send-confirmation" aria-label="Permalink to &quot;The large-send confirmation&quot;">​</a></h2><p>For a large transfer to a stranger, an interstitial appears with a <strong>hold-to-confirm</strong> button. Hold it for a moment, then approve with your passkey. That is the whole gate.</p><p>Being honest about what protects you here: <strong>there is no one-time code, and the barrier is your passkey.</strong> Your passkey signature is cryptographically bound to this exact recipient and amount (the account&#39;s execute challenge covers the call), so it authorizes <em>this transfer and no other</em>. The hold-to-confirm is deliberate friction — it stops a large send to a stranger from happening on a stray tap or a hurried moment — not a second factor.</p><p>An earlier version issued a &quot;one-time code&quot; here. It was removed because the guardian minted that code automatically from the same passkey signature that authorized the send: the same key produced both, so the code added no independent security while appearing to. Suho does not ship security theater. A <strong>real</strong> second factor — an out-of-band code delivered to your recovery email, which survives a stolen passkey — is planned as account-level hardening (see the security notes); it is deliberately absent until it can be built so nothing can bypass it.</p><p>The on-chain behavior — a large unverified send completes on passkey authority, emits <code>UnverifiedLargeSend</code>, and consumes no code, while the same send with a wrong passkey reverts — is proven by the guard fork tests (<code>contracts/test/OndolGuard.t.sol</code>).</p>',16)])])}const g=a(o,[["render",s]]);export{p as __pageData,g as default};
